-- CookAI setup part 2: fixes + seed recipes.
-- Run in Supabase > SQL Editor AFTER cookai_schema.sql. Safe to run more than once.

-- ───────── Fix 1: guests ("Continue as Guest") can browse recipes ─────────
drop policy if exists profiles_read on profiles;
create policy profiles_read on profiles for select to anon, authenticated using (true);
drop policy if exists recipes_read on recipes;
create policy recipes_read on recipes for select to anon, authenticated
  using (status = 'visible' or uploader_id = auth.uid() or is_admin());
drop policy if exists ratings_read on ratings;
create policy ratings_read on ratings for select to anon, authenticated using (true);
drop policy if exists likes_read on likes;
create policy likes_read on likes for select to anon, authenticated using (true);
drop policy if exists comments_read on comments;
create policy comments_read on comments for select to anon, authenticated using (true);

-- ───────── Fix 2: protection triggers only apply to app users, not the SQL Editor ─────────
create or replace function protect_recipe_fields() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if pg_trigger_depth() = 1 and auth.uid() is not null and not is_admin() then
    new.status := old.status; new.moderation_reason := old.moderation_reason; new.moderated_by := old.moderated_by;
    new.uploader_id := old.uploader_id; new.source := old.source;
    new.rating_average := old.rating_average; new.rating_count := old.rating_count;
    new.like_count := old.like_count; new.save_count := old.save_count;
  end if;
  return new;
end $$;

create or replace function protect_profile_fields() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if pg_trigger_depth() = 1 and auth.uid() is not null then
    new.role := old.role; new.is_verified := old.is_verified;
    new.recipes_count := old.recipes_count; new.total_likes := old.total_likes; new.email := old.email;
  end if;
  return new;
end $$;

create or replace function force_recipe_defaults() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null and not is_admin() then
    if new.source = 'library' then new.source := 'community'; end if;
    new.status := 'visible'; new.moderation_reason := null; new.moderated_by := null;
    new.rating_average := 0; new.rating_count := 0; new.like_count := 0; new.save_count := 0;
  end if;
  return new;
end $$;

