values ('00000000-0000-0000-0000-000000000103', 'Street Tacos Al Pastor', 'Mexican', 35, 'Medium', 4, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=400&h=300&fit=crop&auto=format', 'library', 'visible', null, '00000000-0000-0000-0000-000000000001',
  '[{"id": "b7a509c3-a313-4915-bc03-70f5a45f92c3", "name": "Pork shoulder, thinly sliced", "quantity": "700g", "category": "Meat & Fish"}, {"id": "e8e124e5-89a9-418a-9848-d707fe2663b2", "name": "Dried guajillo chiles", "quantity": "3", "category": "Pantry"}, {"id": "fb669238-81c5-41a3-9076-53abdd1768ba", "name": "Pineapple, diced", "quantity": "½", "category": "Produce"}, {"id": "c814dbbc-76c3-4a5b-96d0-a546309d5f52", "name": "White onion, diced", "quantity": "1", "category": "Produce"}, {"id": "4b290f77-b512-45b5-8135-a1eaa5899521", "name": "Garlic", "quantity": "4 cloves", "category": "Produce"}, {"id": "8d8c5982-dfc8-4bf3-8153-33eb16c6d778", "name": "Achiote paste", "quantity": "2 tbsp", "category": "Pantry"}, {"id": "060977fc-1149-42e8-9898-a2e2cc091476", "name": "Apple cider vinegar", "quantity": "2 tbsp", "category": "Produce"}, {"id": "46f52c4a-35af-472e-9b7b-7c3bf0204fd9", "name": "Corn tortillas", "quantity": "12 small", "category": "Pantry"}, {"id": "0fb96656-a9f4-4f94-ba1f-a78fb19e0408", "name": "Fresh cilantro, chopped, a handful", "quantity": "", "category": "Produce"}, {"id": "223a5866-36d1-443c-b926-5eb99fe83949", "name": "Lime wedges, to serve", "quantity": "", "category": "Produce"}]'::jsonb,
