  '[{"id": "478acc9e-7b7b-4dcb-acf7-86d18042a86b", "order": 1, "text": "Mince the garlic and grate the ginger.", "timer_seconds": null, "action": "chop"}, {"id": "f00f916f-5433-499c-b7ab-64a5b40a812a", "order": 2, "text": "Marinate the diced chicken in yogurt, half the garlic and ginger, and 1 tsp garam masala for at least 20 minutes.", "timer_seconds": 1200, "action": "simmer"}, {"id": "cddbbd25-b374-4b83-b196-644459150d48", "order": 3, "text": "Heat 1 tablespoon of butter in a pan over medium-high heat.", "timer_seconds": null, "action": "heat"}, {"id": "bf88fd08-69ac-4712-b843-53a952358b27", "order": 4, "text": "Cook the marinated chicken until browned and mostly cooked through, about 6 minutes.", "timer_seconds": 360, "action": "saute"}, {"id": "15a3bfef-f158-4369-a160-fb7dab2a0989", "order": 5, "text": "Add the remaining garlic, ginger, chili powder, and tomato puree to the pan.", "timer_seconds": null, "action": "tomato"}, {"id": "63cfdcd1-6056-4489-b88b-7cd98fd4fd99", "order": 6, "text": "Simmer the sauce for 10 minutes, then stir in the cream and remaining butter.", "timer_seconds": 600, "action": "simmer"}, {"id": "9b1831c6-8e8b-48f6-9ea3-f37d3f6499ba", "order": 7, "text": "Return the chicken to the sauce and toss to coat. Simmer 5 more minutes and serve over basmati rice.", "timer_seconds": 300, "action": "toss"}]'::jsonb,
  '2026-08-09 12:00:00+08')
on conflict (id) do nothing;

