  '[{"id": "c352e178-a21c-4f7e-9882-eb213e9e67bb", "order": 1, "text": "Slice the tomato and onion, and prepare the lettuce and pickles.", "timer_seconds": null, "action": "chop"}, {"id": "d58d20c2-c667-4a50-9279-c6528194554d", "order": 2, "text": "Divide the beef into 2 loose balls, then heat a skillet over high heat until smoking.", "timer_seconds": null, "action": "heat"}, {"id": "12d0cabc-2138-4913-b976-8fd4eb393bdc", "order": 3, "text": "Place the beef balls in the pan and immediately smash flat with a spatula. Season with salt and pepper.", "timer_seconds": 120, "action": "saute"}, {"id": "19b5edfa-e339-42a0-b960-fc49a007900f", "order": 4, "text": "Flip the patties, top each with a slice of cheddar, and cook 1 more minute until melted.", "timer_seconds": 60, "action": "heat"}, {"id": "87ebe37c-68cd-4776-8295-0a4a6555f69f", "order": 5, "text": "Toast the buns lightly, then assemble with the patty, lettuce, tomato, onion, and pickles.", "timer_seconds": null, "action": "toss"}]'::jsonb,
