  '[{"id": "892ddc4c-442e-49e6-a05c-a20cf9dda426", "order": 1, "text": "Whisk miso, mirin, sake, sesame oil, and sugar into a smooth glaze.", "timer_seconds": null, "action": "chop"}, {"id": "c2134cbb-dbd0-4c47-9ef7-d74075326db8", "order": 2, "text": "Pat the salmon fillets dry and coat generously with the glaze. Marinate 20 minutes.", "timer_seconds": 1200, "action": "simmer"}, {"id": "fb809496-e5cb-4232-afd5-5569c6eb8ca0", "order": 3, "text": "Preheat the oven to 200°C. Line a baking tray with foil.", "timer_seconds": null, "action": "heat"}, {"id": "a48ec08e-cbc8-44b9-9c53-d5147931070a", "order": 4, "text": "Bake the salmon 10–12 minutes until caramelised and just cooked through.", "timer_seconds": 660, "action": "heat"}, {"id": "76f7fa7f-b577-44d4-a789-d01637ffed77", "order": 5, "text": "Garnish with sliced spring onions and sesame seeds. Serve with steamed rice.", "timer_seconds": null, "action": "toss"}]'::jsonb,
  '2026-09-11 12:00:00+08')
