insert into recipes (id, title, cuisine, cook_time_minutes, difficulty, servings, image_url, source, status, moderation_reason, uploader_id, ingredients, steps, created_at)
values ('00000000-0000-0000-0000-000000000202', 'Lamb Kofta with Tzatziki', 'Mediterranean', 35, 'Medium', 4, 'https://images.unsplash.com/photo-1585937421612-70a008356fbe?w=400&h=300&fit=crop&auto=format', 'community', 'visible', null, '00000000-0000-0000-0000-000000000012',
  '[{"id": "852917c3-0678-458b-b49a-fe717f13928f", "name": "Ground lamb", "quantity": "500g", "category": "Meat & Fish"}, {"id": "2d9b6875-85e1-4619-8017-be460b5ad8c5", "name": "Onion, grated", "quantity": "1", "category": "Produce"}, {"id": "b5db0114-649b-41fc-bcb2-de14277a540b", "name": "Garlic, minced", "quantity": "3 cloves", "category": "Produce"}, {"id": "649b406f-1ce0-4061-8174-e8ca6ee76f4f", "name": "Cumin", "quantity": "2 tsp", "category": "Pantry"}, {"id": "273f621e-8ab1-450b-b89d-63263dbb9ce6", "name": "Coriander", "quantity": "1 tsp", "category": "Produce"}, {"id": "2a4243ed-8a9f-464e-a0dd-479bacd0e81f", "name": "Cinnamon", "quantity": "½ tsp", "category": "Other"}, {"id": "ff851e23-ebc7-402b-945d-7f375df8c6fd", "name": "Salt and black pepper, to taste", "quantity": "", "category": "Produce"}, {"id": "a88add15-20e4-46de-bfe2-80b93087bbba", "name": "Fresh parsley, chopped, a handful", "quantity": "", "category": "Produce"}, {"id": "f0670412-43f9-49cd-88df-dc586d8a5578", "name": "Greek yogurt, for tzatziki", "quantity": "", "category": "Dairy & Eggs"}, {"id": "59934585-068d-4ab7-8064-cbe698b9fb3d", "name": "Cucumber, for tzatziki", "quantity": "", "category": "Produce"}, {"id": "4181bfd7-5ef3-4baa-b538-a1167c3e0729", "name": "Dill, for tzatziki", "quantity": "", "category": "Other"}, {"id": "af597d0b-6cd2-4e00-b4e1-060612c6c895", "name": "Lemon, for tzatziki", "quantity": "", "category": "Produce"}]'::jsonb,
  '[{"id": "98a0ede4-50c1-46ba-9fc3-7028e69252ac", "order": 1, "text": "Combine lamb, onion, garlic, spices, and parsley. Mix well.", "timer_seconds": null, "action": "chop"}, {"id": "333824c0-6816-41a3-b93e-449f946290d0", "order": 2, "text": "Shape into 8 oval koftas around metal skewers.", "timer_seconds": null, "action": "toss"}, {"id": "3ccbc0ed-8fcd-4065-8d8f-40ad3ff2e1ff", "order": 3, "text": "Grill over high heat 3–4 minutes per side until charred and cooked.", "timer_seconds": 420, "action": "heat"}, {"id": "4cd007a6-4dc5-4560-81ce-2470be945cae", "order": 4, "text": "Meanwhile, make the tzatziki: grate the cucumber, squeeze dry, and mix with yogurt, dill, and lemon.", "timer_seconds": null, "action": "chop"}, {"id": "cd958216-c2fa-4d1a-969a-35f403fc7eb6", "order": 5, "text": "Serve the koftas with tzatziki, warm flatbread, and sliced tomatoes.", "timer_seconds": null, "action": "toss"}]'::jsonb,
  '2026-09-10 12:00:00+08')
on conflict (id) do nothing;

