  '[{"id": "78b1bb6b-ebed-45a4-b18f-2c5542911040", "order": 1, "text": "Heat a wok over high heat until smoking. Add oil.", "timer_seconds": null, "action": "heat"}, {"id": "8b8b55cd-c9d1-49a0-82d1-ca6c964ec4fa", "order": 2, "text": "Scramble the eggs briefly, then push to the side of the wok.", "timer_seconds": 60, "action": "saute"}, {"id": "cc50ff76-868c-493d-a80f-08b35e1d812a", "order": 3, "text": "Add the prawns and cook 2 minutes. Add the rice and stir-fry 3 minutes.", "timer_seconds": 300, "action": "saute"}, {"id": "e22a93d5-efea-49cc-b707-c7fac433530d", "order": 4, "text": "Add the pineapple, fish sauce, soy sauce, and sugar. Toss well.", "timer_seconds": null, "action": "toss"}, {"id": "cc2ef03b-bcba-47e6-b902-32dcc4b0dbaa", "order": 5, "text": "Serve garnished with cashews and spring onions.", "timer_seconds": null, "action": "toss"}]'::jsonb,
  '2026-09-10 12:00:00+08')
on conflict (id) do nothing;

