  '[{"id": "c0c9ff9c-ecf0-454c-adcb-c4975c604bed", "name": "Store-bought potato gnocchi", "quantity": "500g", "category": "Pantry"}, {"id": "da841df7-b66e-4d5b-bb1f-200494eaacc8", "name": "Unsalted butter", "quantity": "80g", "category": "Pantry"}, {"id": "21a5492a-6dac-402d-99d8-e4720035a116", "name": "Fresh sage leaves", "quantity": "12", "category": "Produce"}, {"id": "32c8e207-87b8-4003-8b9a-8f165b801836", "name": "Garlic, halved", "quantity": "2 cloves", "category": "Produce"}, {"id": "526771a5-5519-44de-9704-622e1ade67e5", "name": "Salt and black pepper, to taste", "quantity": "", "category": "Produce"}, {"id": "504f3660-fce9-48e4-b10d-4e5dc1ca59b7", "name": "Parmesan, freshly grated, to serve", "quantity": "", "category": "Dairy & Eggs"}, {"id": "eddce3c0-7591-4654-abbb-3895bd01cd83", "name": "Lemon zest, to finish", "quantity": "", "category": "Produce"}]'::jsonb,
  '[{"id": "b5e9dfd9-9de4-49b8-bd9f-5c8e25f1602c", "order": 1, "text": "Cook the gnocchi in boiling salted water until they float, 2–3 minutes. Drain.", "timer_seconds": 180, "action": "boil"}, {"id": "c3a4f4ae-6f87-4f58-9412-916d19b28617", "order": 2, "text": "Melt the butter in a wide pan over medium heat. Add the garlic and sage.", "timer_seconds": null, "action": "heat"}, {"id": "54f21850-31d4-4ae0-8650-784edd013d1d", "order": 3, "text": "Cook until the butter turns golden and smells nutty — watch closely.", "timer_seconds": 180, "action": "saute"}, {"id": "7593a279-81a1-440a-9811-4f63bdba05fc", "order": 4, "text": "Remove the garlic. Add the drained gnocchi and toss to coat.", "timer_seconds": null, "action": "toss"}, {"id": "c7490ae1-9d3f-4add-8d36-b71cd450fcac", "order": 5, "text": "Plate immediately, top with Parmesan and lemon zest.", "timer_seconds": null, "action": "toss"}]'::jsonb,
  '2026-09-09 12:00:00+08')
on conflict (id) do nothing;

