  '[{"id": "a33ef3d6-0e9c-42f1-b28d-bd637b28ed05", "order": 1, "text": "Simmer the lentils with turmeric and 600ml water until soft, about 20 minutes.", "timer_seconds": 1200, "action": "simmer"}, {"id": "fd460089-c9ee-499e-a61d-69cecd424193", "order": 2, "text": "Stir in the coconut milk and simmer 5 more minutes.", "timer_seconds": 300, "action": "simmer"}, {"id": "0dc46f07-1db4-4f90-9014-4103ed7915c1", "order": 3, "text": "For the tadka: heat oil, then fry the cumin seeds, onion, garlic, and ginger until golden.", "timer_seconds": 300, "action": "saute"}, {"id": "56d8723e-6701-4d2a-8ed2-a89fe37d5c59", "order": 4, "text": "Add the garam masala to the tadka, cook 1 minute, then pour over the dal.", "timer_seconds": 60, "action": "heat"}, {"id": "eb0db261-fc58-4af2-867c-7a47e05807b8", "order": 5, "text": "Serve with rice or naan and fresh coriander.", "timer_seconds": null, "action": "toss"}]'::jsonb,
